using System;using System.Drawing;
class TestVisibility {static void Check(bool pass,string name){if(!pass)throw new Exception(name);Console.WriteLine("PASS "+name);}static void Main(){var screen=new Rectangle(0,0,2560,1600);var work=new Rectangle(0,0,2560,1540);Check(DesktopVisibilityPolicy.Covered(work,screen,work,true,true),"maximized with taskbar gap");Check(DesktopVisibilityPolicy.Covered(screen,screen,work,true,false),"borderless fullscreen");Check(!DesktopVisibilityPolicy.Covered(new Rectangle(20,20,1000,800),screen,work,true,false),"normal window restores widgets");Check(!DesktopVisibilityPolicy.Covered(screen,screen,work,false,true),"desktop and own windows excluded");Check(!DesktopVisibilityPolicy.Covered(new Rectangle(2560,0,2560,1600),screen,work,true,true),"other monitor excluded");Check(!DesktopVisibilityPolicy.Covered(new Rectangle(0,0,1280,1540),screen,work,true,false),"half screen remains ordinary");Check(!DesktopVisibilityPolicy.IsApplicationSurface(0x08080080),"NVIDIA nonactivating overlay excluded");Check(!DesktopVisibilityPolicy.IsApplicationSurface(0x002800A8),"transparent click-through overlay excluded");Check(DesktopVisibilityPolicy.IsApplicationSurface(0x100),"ordinary app retained");Check(DesktopVisibilityPolicy.IsApplicationSurface(0),"borderless fullscreen retained");var normal=new DesktopWindowState{Bounds=new Rectangle(200,100,900,700),Application=true,Visible=true};
var background=new DesktopWindowState{Bounds=work,Application=true,Visible=true,Maximized=true};
var windows=new[]{normal,background};
Check(DesktopVisibilityPolicy.AnyCovered(windows,screen,work),"normal foreground with maximized background stays hidden");
background.Maximized=false;background.Bounds=screen;
Check(DesktopVisibilityPolicy.AnyCovered(windows,screen,work),"background fullscreen stays hidden");
background.Minimized=true;
Check(!DesktopVisibilityPolicy.AnyCovered(windows,screen,work),"minimized background excluded");
background.Minimized=false;background.Visible=false;
Check(!DesktopVisibilityPolicy.AnyCovered(windows,screen,work),"invisible background excluded");
background.Visible=true;background.Cloaked=true;
Check(!DesktopVisibilityPolicy.AnyCovered(windows,screen,work),"other virtual desktop excluded");
background.Cloaked=false;background.Bounds=new Rectangle(2560,0,2560,1600);
Check(!DesktopVisibilityPolicy.AnyCovered(windows,screen,work),"background on other monitor excluded");
background.Bounds=new Rectangle(20,20,1000,800);
Check(!DesktopVisibilityPolicy.AnyCovered(windows,screen,work),"restored background reveals widgets");
background.Bounds=screen;background.Application=false;
Check(!DesktopVisibilityPolicy.AnyCovered(windows,screen,work),"excluded background cannot hide widgets");
background.Application=true;
var dock=new Rectangle(100,1450,2300,90);
Check(DesktopVisibilityPolicy.OverlapsDock(windows,dock),"background overlap hides dock");
background.Minimized=true;
Check(!DesktopVisibilityPolicy.OverlapsDock(windows,dock),"minimized background cannot hide dock");
var leftRail=new Rectangle(16,350,104,850);
var rightRail=new Rectangle(2440,400,100,750);
var topBar=new Rectangle(16,12,2528,54);
var wechat=new DesktopWindowState{Bounds=new Rectangle(-43,10,1278,788),Application=true,Visible=true};
Check(DesktopVisibilityPolicy.OverlapsComponent(new[]{wechat},leftRail),"ordinary WeChat window hides covered left rail");
Check(DesktopVisibilityPolicy.OverlapsComponent(new[]{wechat},topBar),"ordinary window hides covered top bar");
Check(!DesktopVisibilityPolicy.OverlapsComponent(new[]{wechat},rightRail),"uncovered right rail remains available");
var center=new DesktopWindowState{Bounds=new Rectangle(500,200,1200,1100),Application=true,Visible=true};
Check(!DesktopVisibilityPolicy.OverlapsComponent(new[]{center},leftRail)&&!DesktopVisibilityPolicy.OverlapsComponent(new[]{center},rightRail),"transparent popup areas cannot hide compact rails");
wechat.Minimized=true;
Check(!DesktopVisibilityPolicy.OverlapsComponent(new[]{wechat},leftRail),"minimizing overlapping app restores component");
wechat.Minimized=false;wechat.Visible=false;
Check(!DesktopVisibilityPolicy.OverlapsComponent(new[]{wechat},leftRail),"invisible ordinary app excluded");
wechat.Visible=true;wechat.Cloaked=true;
Check(!DesktopVisibilityPolicy.OverlapsComponent(new[]{wechat},leftRail),"ordinary app on other virtual desktop excluded");
wechat.Cloaked=false;wechat.Application=false;
Check(!DesktopVisibilityPolicy.OverlapsComponent(new[]{wechat},leftRail),"click-through overlay cannot hide rail");
wechat.Application=true;wechat.Bounds=new Rectangle(112,350,500,850);
Check(!DesktopVisibilityPolicy.OverlapsComponent(new[]{wechat},leftRail),"eight-pixel shadow graze does not hide rail");
wechat.Bounds=new Rectangle(2560,0,1200,1500);
Check(!DesktopVisibilityPolicy.OverlapsComponent(new[]{wechat},rightRail),"ordinary window on another monitor excluded");
Check(!DesktopVisibilityPolicy.OverlapsComponent(new[]{center},Rectangle.Empty),"uninitialized component excluded");
}}
